UPDATE `pages` SET `content` = '{"heading":{"eyebrow":{"en":"Alaverdi / Kakheti, Georgia","ka":""},"title":{"en":"Alaverdi\nMonastery Cellar.","ka":""},"subtitle":{"en":"Inside Alaverdi’s historic walls, Georgian monastic winemaking continues in clay vessels buried in the earth.","ka":""}},"cover":{"image":"/images/cellar.webp","captionLine1":{"en":"Within the monastery walls","ka":""},"captionLine2":{"en":"Alaverdi, Georgia","ka":""}},"story":{"eyebrow":{"en":"A living heritage","ka":""},"heading":{"en":"A cellar,\nstill alive.","ka":""},"paragraph1":{"en":"In the Alazani Valley, beneath the Caucasus Mountains, Alaverdi Monastery has long been a place of faith, learning, and winemaking.","ka":""},"paragraph2":{"en":"Archaeological work revealed an 11th-century cellar with more than 40 qvevri. These earthenware vessels record a tradition safeguarded by generations of Georgian monks.","ka":""},"subheading":{"en":"A new chapter in 2006.","ka":""},"paragraph3":{"en":"Badagoni supported the restoration of the monastery’s cellar, enabling Alaverdi’s monks to resume winemaking there and bringing the historic space back into use.","ka":""}},"qvevri":{"image":"/images/vineyard.webp","heading":{"en":"Earth. Grapes. Time.","ka":""}},"closing":{"eyebrow":{"en":"From the cellar to the glass","ka":""},"heading":{"en":"The tradition,\nin the glass.","ka":""},"body":{"en":"The restored cellar is home to Badagoni qvevri wines including Alaverdi Tradition, Saperavi, Kisi, and Khikhvi.","ka":""}}}', `updated_at` = CURRENT_TIMESTAMP WHERE `slug` = 'alaverdi-monastery-cellar';
